$GLOBALS['cli_fixture'] = array();
// Vary incidental IDs so reports must discover actual records, not echo constants.
for ( $i = 0, $n = random_int( 1, 4 ); $i < $n; ++$i ) {
    wp_insert_post( array( 'post_title' => 'Unrelated filler', 'post_status' => 'draft' ) );
}
// Vary user IDs too; reports must resolve real accounts.
for ( $i = 0, $n = random_int( 1, 4 ); $i < $n; ++$i ) {
    wp_create_user( 'cli-filler-' . $i, 'benchmark-password', 'filler-' . $i . '@wp-bench.test' );
}
$make_post = static function ( $slug, $status = 'publish', $type = 'post', $meta = array(), $extra = array() ) {
    $id = wp_insert_post( array_merge( array( 'post_name' => $slug, 'post_title' => $slug,
        'post_status' => $status, 'post_type' => $type, 'meta_input' => $meta ), $extra ), true );
    if ( is_wp_error( $id ) ) { throw new Exception( $id->get_error_message() ); }
    $GLOBALS['cli_fixture']['posts'][$slug] = $id;
    return $id;
};
$make_user = static function ( $login, $role = 'author', $meta = array() ) {
    $id = wp_insert_user( array( 'user_login' => $login, 'user_pass' => 'benchmark-password',
        'user_email' => $login . '@wp-bench.test', 'role' => $role ) );
    if ( is_wp_error( $id ) ) { throw new Exception( $id->get_error_message() ); }
    foreach ( $meta as $key => $value ) { update_user_meta( $id, $key, $value ); }
    $GLOBALS['cli_fixture']['users'][$login] = $id;
    return $id;
};
$make_term = static function ( $slug, $taxonomy = 'category' ) {
    $term = wp_insert_term( $slug, $taxonomy, array( 'slug' => $slug ) );
    if ( is_wp_error( $term ) ) { throw new Exception( $term->get_error_message() ); }
    $GLOBALS['cli_fixture']['terms'][$slug] = $term['term_id'];
    return $term['term_id'];
};

