$names=array('cli_cache_large_a','cli_cache_large_'.substr(wp_generate_uuid4(),0,8));
foreach($names as $name) { add_option($name,array('blob'=>str_repeat('x',random_int(1100,1500)),'enabled'=>false,'count'=>3),'',true); }
