$GLOBALS['cli_fixture']['disable']=$names;
global $wpdb; $GLOBALS['cli_fixture']['options']=array();
foreach(array_merge($names,array('cli_cache_small','cli_cache_already_off','cli_cache','other_cache_large')) as $name) {
    $GLOBALS['cli_fixture']['options'][$name]=$wpdb->get_row($wpdb->prepare("SELECT option_value,autoload FROM {$wpdb->options} WHERE option_name=%s",$name),ARRAY_A);
}
$GLOBALS['cli_fixture']['content_before'] = \WPBench\Runtime\Preservation::capture_posts();

