assertions.code:
$f=$GLOBALS['cli_fixture']; global $wpdb;
foreach($f['options'] as $name=>$before) {
    $actual=$wpdb->get_row($wpdb->prepare("SELECT option_value,autoload FROM {$wpdb->options} WHERE option_name=%s",$name),ARRAY_A);
    if(!$actual || $actual['option_value']!==$before['option_value']) { return false; }
    if(in_array($name,$f['disable'],true)) { if(in_array($actual['autoload'],wp_autoload_values_to_autoload(),true)) { return false; } }
    elseif($actual['autoload']!==$before['autoload']) { return false; }
} return true;
